<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';
import {type Context,type Limits,fetchJson} from './api';
import {type Locale,formName} from './i18n';
const props=defineProps<{context?:Context;limits:Limits;locale:Locale;excludedConnections?:string[];allowMixedDirections?:boolean;purpose?:'add'|'exclude'}>();
const emit=defineEmits<{select:[whole:{key:string;code:string}];change:[keys:string[]]}>();
const copy={en:{title:'Excluded connections',build:'Build a connection',next:'Next part',add:'Add connection',exclude:'Exclude connection',restore:'Restore connection',edit:'Change from this part',reset:'Start again',sequence:'Direct step into Axel assumed',failed:'Connection choices unavailable. Try again.',retry:'Try again',empty:'No connections excluded.',help:'Only this whole connection is excluded. Its jumps and longer connections remain available.'},de:{title:'Ausgeschlossene Verbindungen',build:'Verbindung zusammenstellen',next:'Nächster Teil',add:'Verbindung hinzufügen',exclude:'Verbindung ausschließen',restore:'Verbindung wieder zulassen',edit:'Ab diesem Teil ändern',reset:'Neu beginnen',sequence:'Direkter Schritt in den Axel angenommen',failed:'Verbindungsauswahl nicht verfügbar. Erneut versuchen.',retry:'Erneut versuchen',empty:'Keine Verbindungen ausgeschlossen.',help:'Nur diese ganze Verbindung ist ausgeschlossen. Ihre Sprünge und längere Verbindungen bleiben verfügbar.'},ru:{title:'Исключённые соединения',build:'Составить соединение',next:'Следующая часть',add:'Добавить соединение',exclude:'Исключить соединение',restore:'Восстановить соединение',edit:'Изменить с этой части',reset:'Начать заново',sequence:'Предполагается прямой шаг в аксель',failed:'Варианты соединений недоступны. Повторите попытку.',retry:'Повторить',empty:'Нет исключённых соединений.',help:'Исключается только это соединение целиком. Его прыжки и более длинные соединения остаются доступны.'}};
const labels=computed(()=>copy[props.locale]),prefix=ref<string[]>([]),query=ref(''),failed=ref(false),pending=ref(false),root=ref<HTMLElement>();
interface Part{code:string;form:string;level:number|null}
interface Whole{key:string;code:string;parts:Part[];directTransitionsAssumed:boolean;excluded?:boolean}
interface Options{requestId:string;revision:number;next:string[];nextParts:Part[][];completions:Whole[];excludedConnections:Whole[]}
const options=ref<Options>(),known=ref<Record<string,Whole>>({});let revision=0;
function name(parts:Part[]){return parts.map(p=>`${formName(props.locale,p.form)}${p.level==null?'':` ${p.level===0?'B':p.level}`}`).join(' + ');}
const matches=computed(()=>options.value?.next.filter(code=>`${code} ${name(options.value?.nextParts.find(parts=>parts[0]?.code===code)??[])}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))??[]);
async function load(){const own=++revision;if(!props.context){options.value=undefined;return;}failed.value=false;pending.value=true;const requestId=crypto.randomUUID();try{const next=await fetchJson<Options>('/api/v1/connections/options',{requestId,revision:own,context:props.context,personalLimits:props.limits,prefix:prefix.value,excludedConnections:props.excludedConnections??[],allowMixedDirections:props.allowMixedDirections??false});if(own===revision&&next.requestId===requestId&&next.revision===own){options.value=next;for(const whole of [...next.completions,...next.excludedConnections])known.value[whole.key]=whole;}}catch{if(own===revision){failed.value=true;options.value=undefined;}}finally{if(own===revision)pending.value=false;}}
async function restore(key:string){const keys=props.excludedConnections??[],index=keys.indexOf(key);emit('change',keys.filter(k=>k!==key));await nextTick();const buttons=root.value?.querySelectorAll<HTMLButtonElement>('[data-restore]');(buttons?.[Math.min(index,(buttons?.length??0)-1)]??root.value?.querySelector<HTMLElement>('.connection-builder>summary'))?.focus();}
async function select(whole:Whole){if(props.purpose!=='exclude'){emit('select',whole);return;}if(whole.excluded){const original=options.value?.excludedConnections.find(e=>e.code===whole.code&&e.directTransitionsAssumed===whole.directTransitionsAssumed);if(original)void restore(original.key);return;}if(!(props.excludedConnections??[]).includes(whole.key)){emit('change',[...(props.excludedConnections??[]),whole.key]);await nextTick();const buttons=root.value?.querySelectorAll<HTMLButtonElement>('[data-restore]');buttons?.[buttons.length-1]?.focus();}}
async function setPrefix(next:string[]){prefix.value=next;query.value='';await nextTick();const parts=root.value?.querySelectorAll<HTMLButtonElement>('[data-prefix]');(parts?.[parts.length-1]??root.value?.querySelector<HTMLElement>('[data-reset]'))?.focus();}
watch([prefix,()=>props.context,()=>props.limits,()=>props.excludedConnections,()=>props.allowMixedDirections],load,{deep:true,immediate:true});
</script>
<template>
<div ref="root" :data-testid="purpose==='exclude'?'connection-exclusions':'program-connection-builder'">
<template v-if="purpose==='exclude'"><h2>{{labels.title}}</h2><details><summary>{{locale==='de'?'Was wird ausgeschlossen?':locale==='ru'?'Что исключается?':'What is excluded?'}}</summary><p>{{labels.help}}</p></details><p v-if="!excludedConnections?.length">{{labels.empty}}</p><ul class="excluded-connections"><li v-for="key in excludedConnections" :key="key"><code>{{known[key]?.code??key.split(':').at(-2)}}</code> <span v-if="known[key]">{{name(known[key]!.parts)}}</span> <small v-if="known[key]?.directTransitionsAssumed">{{labels.sequence}}</small> <button data-restore @click="restore(key)">{{labels.restore}} {{known[key]?.code??key.split(':').at(-2)}}</button></li></ul></template>
<details class="connection-builder"><summary>{{labels.build}}</summary><p><template v-for="(part,index) in prefix" :key="index"><button data-prefix :aria-label="`${labels.edit}: ${index+1} (${part})`" @click="setPrefix(prefix.slice(0,index))">{{part}}</button><span v-if="index<prefix.length-1"> + </span></template><span v-if="!prefix.length">—</span> <button data-reset @click="setPrefix([])">{{labels.reset}}</button></p>
<label>{{locale==='de'?'Teil nach Name oder Code suchen':locale==='ru'?'Найти часть по названию или коду':'Find a part by name or code'}}<input type="search" v-model="query"></label>
<div class="connection-options" :aria-busy="pending"><button v-for="part in matches" :key="part" :disabled="pending" @click="setPrefix([...prefix,part])" :aria-label="`${labels.next}: ${part}`">{{part}} · {{name(options?.nextParts.find(parts=>parts[0]?.code===part)??[])}}</button></div>
<p v-if="failed" role="alert">{{labels.failed}} <button @click="load">{{labels.retry}}</button></p>
<div v-for="whole in options?.completions" :key="whole.key"><button :disabled="pending" @click="select(whole)">{{purpose==='exclude'?(whole.excluded?labels.restore:labels.exclude):labels.add}} {{whole.code}}</button> <span>{{name(whole.parts)}}</span> <small v-if="whole.directTransitionsAssumed">{{labels.sequence}}</small></div>
</details></div>
</template>
